function icon(name,cls=''){return `<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.file}"/></svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
const clone=v=>JSON.parse(JSON.stringify(v));
const fmt=v=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v/100);
const cash=v=>'QAR '+fmt(v);
const moneyView=v=>v<0?'('+fmt(-v)+')':fmt(v);
const shortDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short'});
function cents(s){if(!/^-?\d+(\.\d{1,2})?$/.test(String(s).trim()))throw Error('Use decimal amounts with at most two places.'); const n=Number(s);if(!Number.isSafeInteger(Math.round(n*100))||Math.abs(n)>1e9)throw Error('Amount is outside the prototype limit.');return Math.round(n*100);}
function badge(text,color=''){const key=String(text).toLowerCase();color=color||(/approved|cleared|accepted|active|balanced|delivered|archived|received|current|continued|applied|complete|verified/.test(key)?'green':/review|responded|ready/.test(key)?'purple':/overdue|blocked|stale|rejected|changes|declined/.test(key)?'red':/pending|awaiting|requested|draft|planning/.test(key)?'amber':'gray');return `<span class="tag ${color}"><span class="tagdot"></span>${esc(text)}</span>`;}
function btn(text,action,cls='',extra='',ic=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;}
function linkBtn(text,route,cls=''){return `<button class="btn ghost ${cls}" data-route="${route}">${text}${icon('arrow')}</button>`;}
function avatar(initials,color='',size=''){return `<span class="avatar ${color} ${size}">${esc(initials)}</span>`;}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<div class="sub">${sub}</div>`:''}</div>${action}</div>${body}</section>`;}
function metric(label,value,caption,ic,color=''){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ic)}</span></div><div class="metric-value">${value}</div><div class="metric-caption">${caption}</div></div>`;}
function note(text,color='',extra=''){return `<div class="banner ${color}">${icon(color==='red'?'alert':'info')}<p>${text}</p>${extra}</div>`;}
function footer(ref='STE-PRD-001'){return `<footer class="pagefooter"><span>Illustrative records · Browser-only simulation · No live financial or provider actions</span><button data-action="source" data-section="1">${ref} · Requirements reference ${icon('arrow')}</button></footer>`;}
function head(title,sub,actions='',eyebrow=''){return `<div class="pagehead"><div>${eyebrow?`<div class="eyebrow mb16">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
function tabs(items,key){return `<div class="tabs">${items.map(([id,label])=>`<button class="tab ${ui[key]===id?'active':''}" data-action="tab" data-key="${key}" data-id="${id}">${label}</button>`).join('')}</div>`;}
