function changed(reason){const e=E();e.generation++;e.candidate=null;log(reason+' · dependent approvals are now stale');save();}
function isCurrent(key,e=E()){return e.approvals[key]?.generation===e.generation;}
function allNotesClear(e=E()){return e.reviews.every(r=>r.status==='Cleared');}
function allWorkClear(e=E()){return e.workpapers.every(w=>w.status==='Cleared');}
function isAudit(e=E()){return e.service==='External audit';}
function totals(e=E()){
 const rows=clone(e.rows);if(e.journalState==='Applied'&&!e.sourceReflection){const a=rows.find(r=>r.code==='1590'),b=rows.find(r=>r.code==='5200');if(a)a.balance-=e.adjustment;else rows.push({code:'1590',name:'Accumulated depreciation',type:'asset',balance:-e.adjustment});if(b)b.balance+=e.adjustment;else rows.push({code:'5200',name:'Depreciation expense',type:'expense',balance:e.adjustment});}
 const sum=t=>rows.filter(r=>r.type===t).reduce((s,r)=>s+r.balance,0);
 return {rows,assets:sum('asset'),liabilities:-sum('liability'),openingEquity:-sum('equity'),revenue:-sum('revenue'),expenses:sum('expense'),profit:-sum('revenue')-sum('expense'),balance:rows.reduce((s,r)=>s+r.balance,0)};
}
function releaseBlockers(e=E()){const out=[];if(!e.acceptance)out.push('Partner acceptance is pending');if(!e.terms)out.push('Effective terms are not recorded');if(!e.planning)out.push('Planning approval is pending');if(!e.sourceAccepted)out.push('Source trial balance is unaccepted');if(!e.mappingApproved)out.push('Mapping is unapproved');if(totals(e).balance!==0)out.push('Trial balance is unbalanced');if(e.builtGeneration!==e.generation)out.push('Rebuild the package for the current input generation');if(!e.supplements)out.push('Supporting cash-flow/disclosure schedules are missing');if(!allNotesClear(e))out.push('Review points need independent clearance');if(!allWorkClear(e))out.push('Working papers are not all cleared');if(e.reconciliations.some(r=>r.status!=='Cleared'))out.push('Reconciliations are incomplete');if(!isCurrent('manager',e))out.push('Current manager review is missing');if(!isCurrent('client',e))out.push('Current management approval is missing');if(!isCurrent('partner',e))out.push('Current partner authorization is missing');if(e.eqrRequired&&!isCurrent('eqr',e))out.push('Required EQR is incomplete');return out;}
function stage(e){const last=e.releases.at(-1);if(e.archive&&last?.generation===e.generation)return 'Archived';if(last?.generation===e.generation)return last.delivered?'Delivered':'Demo issued';if(e.builtGeneration!==e.generation)return 'Changes required';if(!e.acceptance||!e.terms)return 'Onboarding';if(!e.planning)return 'Planning';if(releaseBlockers(e).length===0)return 'Ready to issue';return e.stage;}
function percent(e){const v=[e.acceptance,e.terms,e.planning,e.sourceAccepted,e.mappingApproved,e.builtGeneration===e.generation,allNotesClear(e),allWorkClear(e),isCurrent('manager',e),isCurrent('client',e),isCurrent('partner',e),!e.eqrRequired||isCurrent('eqr',e),e.releases.length>0,!!e.archive];return Math.round(v.filter(Boolean).length/v.length*100);}
