 'prepare-release':async()=>{if(!roleAllowed('partner'))return;const e=E(),blockers=releaseBlockers();if(blockers.length)throw Error(blockers.join('; '));const manifest={kind:'SYNTHETIC_DEMO_NOT_FOR_PROFESSIONAL_USE',engagement:e.id,client:e.client,revision:e.packageRevision,generation:e.generation,totals:totals(e),approvals:clone(e.approvals)};const serialized=JSON.stringify(canonical(manifest));const hash=await sha256(serialized);if(e.generation!==manifest.generation||e.packageRevision!==manifest.revision)throw Error('The package changed during candidate creation. Try again.');e.candidate={manifest,serialized,hash,revision:e.packageRevision,generation:e.generation};log('Exact demo release candidate prepared',e.id,'lock');render();toast('Candidate manifest frozen and hashed locally.');},
 'issue-release':()=>{if(!roleAllowed('partner'))return;const e=E(),c=e.candidate;if(!c)throw Error('Prepare a release candidate first.');if(releaseBlockers().length||c.generation!==e.generation||c.revision!==e.packageRevision)throw Error('The release candidate is stale or its gates are incomplete.');if(e.releases.some(r=>r.hash===c.hash)){toast('That exact candidate already has a demo release event. No duplicate created.');return;}const r={id:'REL-'+String(e.releases.length+1).padStart(3,'0'),generation:c.generation,revision:c.revision,hash:c.hash,manifest:clone(c.manifest),serialized:c.serialized,totals:clone(c.manifest.totals),author:actor().name,issuedAt:new Date().toLocaleString('en-GB'),delivered:false,artifact:plainReport(e,{totals:c.manifest.totals,revision:c.revision,generation:c.generation})};e.releases.push(r);log('Demo-only release event created: '+r.id,e.id,'lock');render();toast('Demo package issued locally. No report was sent or legally signed.');},
 'demo-deliver':d=>{if(!roleAllowed(['partner','records']))return;const r=E().releases.find(r=>r.id===d.id);if(!r)return;if(r.delivered){toast('Delivery already recorded; no duplicate created.');return;}r.delivered=true;log('Delivery simulation recorded for '+r.id,r.id,'send');render();toast('Demo delivery recorded. No email or provider request was made.');},
 'released-preview':d=>{const r=E().releases.find(r=>r.id===d.id);if(r)openModal(r.id+' · preserved demo package',`<p class="caption mb16">This is a frozen preview saved at demo issuance. Working-source changes do not rewrite it.</p><iframe title="Preserved illustrative report" style="width:100%;height:65vh;border:1px solid #e1e8e6;border-radius:8px" sandbox srcdoc="${esc(r.artifact)}"></iframe>`,`${btn('Close','close-modal')}${btn('Export issued demo HTML','released-download','soft',`data-id="${r.id}"`,'download')}`,true);},
